import{_ as o,l as c,o as a,c as n,v as t,p,x as r,d as s,i as l,S as f}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"ftrace 与 tracepoints","description":"","frontmatter":{"title":"ftrace 与 tracepoints","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ftrace-tracepoints.md","filePath":"cs/ftrace-tracepoints.md","lastUpdated":1789023840000}'),d={name:"cs/ftrace-tracepoints.md"};function h(u,e,_,m,T,g){const i=c("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="ftrace-与-tracepoints" tabindex="-1">ftrace 与 tracepoints <a class="header-anchor" href="#ftrace-与-tracepoints" aria-label="Permalink to &quot;ftrace 与 tracepoints&quot;">​</a></h1><div class="epigraph"><p>tracepoint 是编译进内核的钩，默认几乎为零成本；ftrace 把它们接到环形缓冲，并可做函数图与过滤。</p><footer>—— 据 Rostedt 对 ftrace 的论述；Linux tracepoint 文档；[printk](/cs/printk-logging) 为重日志对照</footer></div><p><a href="/cs/printk-logging">printk</a> 太重。<a href="/cs/napi">NAPI</a> 路径不能每包打印。缺口是 <strong>ftrace</strong>：tracepoint、function tracer、ring。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>TRACE_EVENT</code> 定义字段。启用才把探针插入。缺口：buffer per-cpu；过滤 pid/comm；function tracer 用 mcount。本课不把每个事件名列出。</p><p><span class="marginnote">tracefs 是接口。对象是事件流，不是 gdb。与 eBPF 后课可共用 tracepoint。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>echo 1 &gt; events/.../enable</code> → 事件写 per-cpu 缓冲 → <code>trace_pipe</code> 读。对照 <a href="/cs/perf-sampling">perf</a> 后课：perf 可消费同一点。对照 <a href="/cs/inotify">inotify</a>：一个文件树，一个内核执行点。对照 ASan：一个找空间错，一个找时间线。</p>',8)),(a(),p(f,null,{default:r(()=>[l(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TP%5B%22tracepoint%22%5D%20--%3E%20FILT%5B%22%E8%BF%87%E6%BB%A4%E5%99%A8%22%5D%0A%20%20FILT%20--%3E%20BUF%5B%22per-CPU%20%E7%8E%AF%22%5D%0A%20%20BUF%20--%3E%20USER%5B%22trace_pipe%20%2F%20perf%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ftrace 把「生产内核可观测」收成零开销默认 + 按需启用，是调试延迟与调度的主工具。不要写成 APM 产品。与 <a href="/cs/preempt-rt">PREEMPT_RT</a>：tracer 本身扰动，要测开/关。</p><p>错误过滤仍可让缓冲溢出丢事件。</p><p>实现上：per-cpu 缓冲避免全局锁，读的时候可能看到撕裂，工具用页头同步。function tracer 用 mcount/patchable 入口，和 livepatch 抢同一套改代码机制。 读法上只引用<a href="/cs/printk-logging">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>ftrace 与 tracepoints</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 tracer 插件。不保证模块事件的稳定性。下一课动态打点：kprobes。</p><p>版本字段会变，课序钉的是机制对象「ftrace 与 tracepoints」，不是某一主线内核的结构体名。 后课默认：静态 tracepoint 可低成本启用。动态探针 kprobe/uprobe，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tracepoint 默认便宜；ftrace 收集到 per-CPU 环。</li><li>函数跟踪更重，适合短时。</li><li>kprobes 是下一课。</li><li>出处：ftrace 文档；Rostedt；tracepoint。</li></ul>',11))])}const k=o(d,[["render",h]]);export{P as __pageData,k as default};
